    ["06b9281"] = "Авто",
    ["f67c1df"] = "BuildBeast: руководство по прокачке с 1 до 60",
    ["0e7837f"] = "Создано Sairiin.",
    ["aa578f8"] = "BuildBeast подсказывает, уровень за уровнем, что делать с вашим персонажем: какой талант взять, какие умения вы получаете, как ими пользоваться, какой предмет надеть. Работает со всеми классами и всеми специализациями.",
    ["23fcc71"] = "Как пользоваться",
    ["0e08901"] = "%s Откройте окно кнопкой у миникарты (левый щелчок) или командой %s. Правый щелчок открывает Настройки.",
    ["6cc5250"] = "%s Вверху выберите свою специализацию. Та, которую распознаёт Hekili, уже выбрана; у специализаций без справки написано «скоро».",
    ["c874e74"] = "%s Вкладка %s: талант, который нужно взять сейчас, новые умения и как ими пользоваться. Стрелками < > смотрите соседние уровни.",
    ["0a729cf"] = "%s Вкладка %s: весь план 51 очка. В окне талантов игры вы увидите цветные отметки: золотой +N = очки к трате, зелёный OK = всё в порядке, синий Ур. = следующее очко придёт на этом уровне, красный X = слишком много очков.",
    ["a3d0c80"] = "%s Вкладка %s: как играть на каждом этапе уровней. Если есть Hekili, нужные кнопки подсвечиваются на панелях: золотой = сейчас, синий = следующая, серый = ожидание.",
    ["cf02e3c"] = "%s Вкладка %s: как я оцениваю предметы. В подсказке вы читаете ДА, НЕТ или ПОХОЖЕ по сравнению с надетым, с причиной; в сумках появляется зелёная стрелка, красная стрелка или жёлтая черта.",
    ["e1a76f0"] = "%s Вкладка %s: полезные макросы для вашей специализации. Кнопка создаёт их в игре, затем вы перетаскиваете их на панели.",
    ["28d51f6"] = "%s Маленькая рамка на экране напоминает о следующем таланте. Внизу окна + и - меняют размер текста.",
    ["6467ab9"] = "Рекомендуемая настройка",
    ["de97971"] = "- Установите %s (ротация) и %s (предметы и чары): BuildBeast дополняет и переводит их.",
    ["91b9278"] = "- При первой установке BuildBeast сам задаёт рекомендуемые настройки (например убирает строки ItemID и IconID из подсказок). В Настройках есть кнопка, возвращающая всё как было.",
    ["1e172e7"] = "- Если другой аддон рисует свои стрелки на значках сумки, отключите его стрелки: две стрелки на одном предмете противоречат друг другу.",
    ["86e0907"] = "- Порог оценки (Настройки, раздел Предметы) определяет, насколько предмет должен быть лучше, чтобы получить ДА или НЕТ. По умолчанию 1: повысьте, если хотите видеть больше ПОХОЖЕ.",
    ["2071055"] = "- Цифры перезарядки на умениях и подсветка кнопок включаются и выключаются в Настройках.",
    ["4703f44"] = "- Язык меняется в Настройках (раздел Язык).",
    ["13ceb3e"] = "Команды",
    ["e388b8c"] = "%s  открывает окно     %s  настройки     %s  эта страница",
    ["1cabadd"] = "%s  что предлагает Hekili     %s  проверяет значки",
    ["0886241"] = "%s  применяет ротацию BuildBeast к Hekili",
    ["61e140b"] = "Скрыть панель (включается в Настройках)",
    ["9478521"] = "BuildBeast: следующий талант",
    ["d41fe44"] = "сейчас",
    ["6bd236d"] = "уровень %s",
    ["6534b74"] = "возьмите талант %s",
    ["21b440a"] = "новые умения: %s",
    ["c77f296"] = "(/bb для справки)",
    ["92682be"] = "Создано Sairiin",
    ["84f646b"] = "Левый щелчок: справка для вашего уровня",
    ["13337ad"] = "Правый щелчок: настройки",
    ["16ed988"] = "команды:",
    ["fec6356"] = "справка",
    ["deced62"] = "меню со всеми настройками",
    ["3f40eb4"] = "что предлагает Hekili",
    ["d0885a3"] = "ротация в Hekili",
    ["0e3c52e"] = "подсветка кнопок",
    ["87b77ec"] = "цифры перезарядки",
    ["39c5501"] = "затенение",
    ["b386ac1"] = "отметки талантов Zygor",
    ["043bf3a"] = "проверка талантов",
    ["e4a27ff"] = "как пользоваться",
    ["2c0595e"] = "проверка значков",
    ["04802c3"] = "Вы не можете это использовать: игра отмечает предмет красным (тип брони или оружия, недоступный вашему классу).",
    ["da5f3b2"] = "В этом слоте у вас ничего нет.",
    ["7064fba"] = "Вы получаете:",
    ["3402ef1"] = "Вы теряете:",
    ["e568035"] = "УВС оружия дальнего боя (или жезла):",
    ["270cb3d"] = "Для вашей специализации это важнее всего.",
    ["759646f"] = "УВС оружия ближнего боя:",
    ["620e128"] = "но ваша специализация не бьёт этим оружием и не использует его.",
    ["f8fc3c4"] = "что важно для вашей специализации.",
    ["4842b23"] = "Остальные различия (броня, урон...) для вашей специализации не важны.",
    ["46e81de"] = "Важные для вас характеристики одинаковы.",
    ["984170a"] = "Для вашей специализации в этом слоте важнее всего: %s.",
    ["8878fa5"] = "Ротация Beast Mastery из справки (прокачка 1-60): без ближнего боя; Hunter's Mark и Serpent Sting в начале, ястребы (Summon Hawk) с 25, Aimed Shot и Arcane Shot, Multi-Shot и Explosive Trap против нескольких монстров. Умения с долгой перезарядкой (Bestial Wrath, Rapid Fire, расовые) вынесены из ротации, их применяют вручную. Создана BuildBeast.",
    ["3fcb6ff"] = "Ротация BuildBeast для прокачки с 1 по 60 уровень из гида: Hekili выбирает из неё только те умения, которые вы уже изучили. Создана BuildBeast.",
    ["f7219d4"] = "для этой специализации у BuildBeast пока нет своей ротации: Hekili использует свою.",
    ["f23ecca"] = "Hekili не загружен.",
    ["2ec553f"] = "Не удалось создать приоритет в Hekili.",
    ["9e1f59d"] = "Hekili уже использует приоритет: %s",
    ["bbf6862"] = "приоритет Hekili задан: %s",
    ["3f1c97f"] = "Hekili не принял приоритет.",
    ["511ff29"] = "подсветка кнопок:",
    ["c172ef4"] = "включена",
    ["72960be"] = "выключена",
    ["969f47a"] = "Золотой = применить сейчас, синий = следующая.",
    ["2850cfb"] = "затенение перезарядок:",
    ["c4ad91d"] = "видимо",
    ["aba8815"] = "скрыто",
    ["babe955"] = "цифры перезарядки на кнопках:",
    ["48983fc"] = "включены",
    ["3424735"] = "выключены",
    ["8b823dc"] = "Zygor не готов.",
    ["7496082"] = "отметки талантов Zygor:",
    ["1b9f260"] = "Откройте окно талантов заново.",
    ["7c4161e"] = "Вы меняете цель, не прерывая Auto Shot.",
    ["3ddfa3b"] = "Питомец атакует цель, которую вы помечаете Hunter's Mark.",
    ["d00e00c"] = "Одна кнопка для умений ближнего боя, когда вас атакуют.",
    ["458bcf6"] = "Чередует Mongoose Bite и Counterattack одной кнопкой после уклонения или парирования.",
    ["7e3322d"] = "Применяет умение и запускает автоатаку, даже до начала боя. Вместо Heroic Strike можно поставить другое умение. Нужно достаточно ярости.",
    ["4215a24"] = "Sunder Armor по врагу под курсором, без выбора цели.",
    ["fade647"] = "Blessing of Protection на союзника под курсором (если его нет, на вашу цель).",
    ["0ea3265"] = "Blessing of Freedom на союзника под курсором.",
    ["474ed6a"] = "Cleanse на союзника под курсором.",
    ["dd398c9"] = "Призывает Advanced Target Dummy на курсор и накладывает на него Blessing of Protection: нажмите дважды, когда нет активного общего восстановления.",
    ["ad171ca"] = "Divine Shield на вас; повторное нажатие сразу снимает его. Нажмите дважды, когда нет активного общего восстановления.",
    ["8b1f0a2"] = "Запускает автоатаку и применяет Holy Strike. Не ставьте на Holy Shield.",
    ["39da0a5"] = "Power Word: Shield на курсор, иначе на вас.",
    ["885b4fd"] = "Greater Heal на курсор, иначе на цель, иначе на вас.",
    ["f6044e4"] = "Прерывает текущее заклинание и снова применяет Greater Heal: на случай, если другой лекарь уже исцелил эту цель.",
    ["73afb8f"] = "Inner Focus и сразу Prayer of Healing: для экстренных случаев.",
    ["91996ef"] = "Умный Dispel Magic: снимает вредную магию с союзников и полезную с врагов.",
    ["b32d1df"] = "Prayer of Mending на курсор, иначе на цель, иначе на вас.",
    ["4e5454e"] = "Прерывает заклинание и применяет Shadow Word: Death по почти мёртвому убегающему монстру или по тотему.",
    ["4b2ea52"] = "Наносит Deadly Poison на оружие основной руки; значок показывает длительность.",
    ["73d1f2d"] = "Наносит Instant Poison на оружие второй руки; значок показывает длительность.",
    ["672d6cc"] = "Pick Pocket как начало, затем Garrote (можно заменить на Cheap Shot или Ambush).",
    ["c2da64b"] = "Отправляет питомца и персонажа в атаку одной кнопкой: так вы не стоите на месте при прокачке.",
    ["8833bc9"] = "Как BB Attacco, но ещё применяет Stormstrike (вместо предыдущего макроса).",
    ["79e760c"] = "Totemic Projection туда, где курсор.",
    ["93ec012"] = "Nature's Swiftness и сразу Healing Wave на курсор: мгновенное экстренное исцеление. Уберите [@mouseover], если не хотите лечить по курсору.",
    ["ddfe74e"] = "Polymorph на цель в фокусе; если её нет или это не враг, на текущую цель.",
    ["425c144"] = "Использует оба аксессуара одной кнопкой (слоты 13 и 14).",
    ["23fc3c4"] = "Combustion вместе с обоими аксессуарами.",
    ["6d5d784"] = "Посылает питомца в атаку и затем ставит его в пассивный режим, как в справке.",
    ["3b9d855"] = "Amplify Curse и Bane of Agony вместе: для начала боя или когда Amplify Curse готов.",
    ["67eb4db"] = "Drain Life, который можно нажимать несколько раз, не прерывая его.",
    ["c24583f"] = "Corruption на цель под курсором: чтобы накладывать DOT на нескольких врагов. Замените Corruption на другой DOT.",
    ["de046d0"] = "Fel Domination и сразу Imp: чтобы вернуть питомца после смерти или для сборки на добивание.",
    ["0da2d35"] = "Fel Domination и сразу Succubus: чтобы вернуть питомца после смерти.",
    ["701f8c9"] = "Bane of Havoc на цель под курсором.",
    ["6177927"] = "Immolate на фокус (цель Bane of Havoc).",
    ["687eb32"] = "Corruption на фокус.",
    ["dfc9982"] = "Bane of Doom на фокус.",
    ["f14c9c9"] = "Bane of Agony на фокус.",
    ["37f2591"] = "Hurricane, который не прерывает сам себя, если нажать кнопку во время чтения заклинания.",
    ["e041704"] = "Moonfire на курсор: чтобы накладывать DOT на нескольких врагов (замените на Insect Swarm для второго).",
    ["11b387e"] = "Feral Charge (кошка), затем Prowl, если вы ещё не в скрытности.",
    ["9bca5ec"] = "Меняет облик, чтобы освободиться от корней и замедлений: из медведя в кошку, из кошки в кошку.",
    ["38e0846"] = "Одна кнопка: Aquatic Form в воде, Travel Form на открытой местности, иначе Cat Form.",
    ["53406a7"] = "Входит в Dire Bear Form один раз, не выходя из неё при повторном нажатии.",
    ["b18da61"] = "Growl на фокус, затем на курсор, затем на цель.",
    ["beb6029"] = "Nature's Swiftness и сразу Healing Touch: мгновенное экстренное исцеление (выходит из облика и прерывает заклинание).",
    ["8c5c182"] = "В бою нельзя создавать макросы: попробуйте позже.",
    ["e3c93a8"] = "Макросы: создано %d, обновлено %d%s. Откройте их через /macro и перетащите на панели.",
    ["99effc3"] = "не создано %d (у вас уже 18 макросов персонажа)",
    ["530c645"] = "Для этой специализации нет макросов.",
    ["1e74c8f"] = "BuildBeast создаст %s макросов для вашего персонажа:\n%s\n\nЕсли они уже есть, он их обновит. Затем вы перетащите их на панели.",
    ["d8354a3"] = "Создать",
    ["160009a"] = "Отмена",
    ["054716f"] = "Воин",
    ["3e76e85"] = "Паладин",
    ["69c8129"] = "Охотник",
    ["dd6c053"] = "Разбойник",
    ["3a3f441"] = "Жрец",
    ["fabeb14"] = "Шаман",
    ["a5a0a92"] = "Маг",
    ["8b0635d"] = "Чернокнижник",
    ["3d8e8ed"] = "Друид",
    ["ce774d9"] = "ДА",
    ["c2f3f48"] = "НЕТ",
    ["672c529"] = "ПОХОЖЕ",
    ["656ff24"] = "Bear Form, Growl, Maul (классовое задание), Nature's Grasp, Demoralizing Roar",
    ["50d1ea3"] = "Bash; задание на Cure Poison",
    ["2290f2a"] = "Swipe; задание на Aquatic Form",
    ["227f378"] = "Faerie Fire (теперь и в облике), Hibernate",
    ["469f184"] = "Cat Form (задание), Prowl, Claw, Rip, Shred, Starfire, Rebirth, Omen of Clarity",
    ["eda7053"] = "Mark of the Wild на себя. Начинайте с Wrath и продолжайте им. Когда мана на исходе, добивайте монстра оружием, так мана вернётся. Лечитесь Healing Touch между боями.",
    ["3d495a9"] = "Держите на себе Mark of the Wild и Thorns и накладывайте Rejuvenation перед боем. Начинайте с Wrath, добавьте Moonfire и продолжайте Wrath. В людной зоне начинайте с Moonfire, он мгновенный.",
    ["bb21cc8"] = "Классовое задание даёт Bear Form, Growl и Maul. Nature's Grasp обездвиживает следующего монстра, который вас ударит; Demoralizing Roar нужен для облика медведя.",
    ["a9ba21f"] = "Enrage даёт ярость сразу и ещё через 10 секунд, но снижает вашу броню.",
    ["9c7f3ca"] = "Feral — специализация кошки и медведя и самая плавная в прокачке: Prowl и Dash переносят вас от цели к цели, и вы почти не останавливаетесь из-за маны. В Bear Form: Mark of the Wild и Thorns на себя, а ярость от ударов пусть оплачивает Maul, который добавляет урон следующему удару. Против нескольких монстров Demoralizing Roar, чтобы ослабить их.",
    ["ce230c2"] = "В Bear Form: Enrage перед боем (потеря брони менее заметна), Faerie Fire снижает броню монстра, Swipe — заполнитель, а Maul тратит оставшуюся ярость. С несколькими монстрами сначала Demoralizing Roar, затем Swipe.",
    ["78a0920"] = "Cat Form: сначала Mark of the Wild и Thorns. Начинайте из Prowl с Shred (Prowl выводит вас за спину монстра), затем Faerie Fire, затем Claw, чтобы набирать приёмы в серии, или Shred, когда вы позади. С четырьмя и более приёмами Rip, если монстр проживёт достаточно. Bear Form остаётся лучше против нескольких монстров: у облика кошки нет ничего, что бьёт больше одного.",
    ["540175c"] = "Rake: начинайте из Prowl с Shred, Faerie Fire, затем Rake и держите его кровотечение всегда активным на монстре, который живёт достаточно долго; затем Claw или Shred со спины. С 4 и более приёмами: Rip, если монстр жив, Ferocious Bite для добивания.",
    ["87e3251"] = "Lacerate (медведь): кровотечение, которое накапливается до 5 раз; против одного монстра это ваш заполнитель, а Maul тратит оставшуюся ярость. С несколькими монстрами Demoralizing Roar, затем Swipe. Blood Frenzy: в облике медведя каждый крит даёт 5 ярости, в облике кошки крит умением с приёмами в серии даёт ещё один.",
    ["25dc320"] = "Predatory Discipline: Ferocious Bite всё ещё получает урон от лишней энергии, но не тратит её.",
    ["042c952"] = "Ravage: начинайте из Prowl с Ravage (нужно быть за спиной монстра), затем Faerie Fire, Rake с всегда активным кровотечением, затем Claw или Shred со спины; с 4 и более приёмами Rip или Ferocious Bite для добивания. Poised отнимает 10 энергии у первого удара, если вы начинаете с полной энергией.",
    ["4560b4d"] = "Dire Bear Form: Enrage перед боем, Faerie Fire, Primal Bite при каждой перезарядке (сильный укус с перезарядкой 6 секунд и большой угрозой), Lacerate между ними против одного монстра и Maul, чтобы потратить остаток; с несколькими монстрами Demoralizing Roar и Swipe вместо Lacerate.",
    ["ff10d54"] = "Кошка: Shifting Power, когда у вас меньше 50 энергии (превращает ману в 40 энергии, перезарядка 8 секунд).",
    ["0d8ecd7"] = "Feral прежде всего хочет урон в секунду оружия, потому что ваш облик строится на нём, а скорость оружия не важна. Затем Меткость (Hit), крит, Ловкость и Сила.",
    ["4a841e3"] = "Guardian — это медведь: он использует тот же план талантов, что и Feral. Bear Form с Mark of the Wild и Thorns на себе; ярость от ударов оплачивает Maul. Против нескольких монстров Demoralizing Roar.",
    ["7b551a8"] = "Enrage перед боем, Faerie Fire на монстра, Swipe как заполнитель и Maul с оставшейся яростью. С несколькими монстрами Demoralizing Roar, затем Swipe.",
    ["af4c8fb"] = "Lacerate — ваш заполнитель против одного монстра (накапливается до 5 раз); Maul тратит оставшуюся ярость. С несколькими монстрами Demoralizing Roar и Swipe.",
    ["5213241"] = "Dire Bear Form: Enrage перед боем, Faerie Fire, Primal Bite при каждой перезарядке (6 секунд, большая угроза), Lacerate между ними против одного монстра и Maul для остального; с несколькими монстрами Demoralizing Roar и Swipe вместо Lacerate.",
    ["fc61247"] = "Медведь хочет урон в секунду оружия (скорость не важна), затем Меткость (Hit), крит, Ловкость и Силу. Для облика медведя подойдут также Сила и сила заклинаний, а Выносливость важнее, если вы танкуете.",
    ["25acd2a"] = "Balance и Restoration начинают одинаково: Improved Wrath (на полсекунды короче чтение и вдвое меньше маны) и Nature's Focus. Balance стартует медленно, но ускоряется, когда Insect Swarm добавляется к Moonfire на каждом монстре.",
    ["9c1fb9f"] = "Mark of the Wild и Thorns на себя, Rejuvenation перед боем. Начинайте с Wrath или с Moonfire, если зона людная. Moonfire и Insect Swarm на монстра (DOT, который ещё и снижает его шанс попасть), затем Wrath. Regrowth, если нужно лечение, Nature's Grasp до прихода второго монстра.",
    ["7f51b3b"] = "Moonfire и Insect Swarm на каждого монстра, с которым вы сражаетесь, затем Wrath. С тремя и более монстрами Hurricane.",
    ["c845919"] = "С тремя и более монстрами Barkskin, затем Hurricane.",
    ["d66aa4c"] = "Eclipse: каждый Wrath убирает полсекунды у ваших двух следующих Starfire, так что Starfire наконец входит в ротацию: один Wrath, затем два Starfire.",
    ["7e94c11"] = "Moonkin Form: много брони, 3% крита для группы, и Omen of Clarity срабатывает вдвое чаще; в этом облике нельзя читать лечение, поэтому выйдите ради Regrowth и войдите снова. Ротация: Moonfire и Insect Swarm, затем один Wrath и два Starfire.",
    ["ef6797a"] = "Для Balance и Restoration на первом месте сила заклинаний, затем Интеллект, крит и Дух; Restoration добавляет силу исцеления на 60. Посох заклинателя может достаться за задание фракции.",
    ["a91a8ac"] = "Restoration прокачивается медленнее всех, потому что лечение не убивает монстров: можно качаться как Balance или Feral и всё равно лечить в подземельях.",
    ["7a2110b"] = "Mark of the Wild и Thorns на себя, Rejuvenation перед боем. Начинайте с Wrath или Moonfire в людной зоне, затем Moonfire и Insect Swarm на монстра и Wrath. Regrowth, если нужно лечение, Nature's Grasp до прихода второго монстра.",
    ["937f66e"] = "Swiftmend: мгновенное исцеление того, на ком ваш Rejuvenation или Regrowth. Когда вы получаете урон, Swiftmend на ваш Rejuvenation, затем Regrowth, если нужно больше. С тремя и более монстрами Hurricane.",
    ["2061d06"] = "Nature's Swiftness: ваше следующее заклинание природы мгновенное. Держите его вне ротации, на тот момент, когда нужно большое исцеление немедленно.",
    ["1164b95"] = "Wild Growth: лечит цель и её группу в течение 7 секунд, сильнее в начале: в группе, когда ранены несколько человек.",
    ["8f8a34a"] = "Aspect of the Hawk, приручение питомца (классовое задание: Tame Beast, Call Pet, Feed Pet, Revive Pet)",
    ["2b3db50"] = "Auto Shot запускается сам: стойте неподвижно полсекунды перед каждым выстрелом и дайте монстру подойти. Raptor Strike, если он добрался до вас. Ближе 8 метров стрельба на расстоянии не работает.",
    ["9329f10"] = "Добавьте Serpent Sting в начале, только на монстров, которые живут долго: если он умрёт за пару секунд, урон пропадёт.",
    ["d2b7bf1"] = "Hunter's Mark перед боем, затем Serpent Sting. Arcane Shot, когда есть мана.",
    ["85f72cd"] = "Основа — Auto Shot, с Arcane Shot, когда есть мана. Перед боем Hunter's Mark, затем Serpent Sting в начале. Пока монстр бежит к вам, Concussive Shot замедляет его; Raptor Strike, если он добрался.",
    ["71067ff"] = "У вас есть питомец: пошлите его вперёд на несколько секунд, затем Serpent Sting. Всегда держите Aspect of the Hawk и кормите питомца. Concussive Shot, если монстр повернулся к вам, Raptor Strike как крайняя мера.",
    ["bb6f64b"] = "Rapid Fire (+40% к скорости атаки на 15 секунд) остаётся вне ротации: берегите его для боя, где он нужен.",
    ["ebe54cf"] = "Основа — Aimed Shot каждый раз, когда он готов (2 секунды чтения, перезарядка 6 секунд общая с Multi-Shot), с Auto Shot в промежутках. Перед боем Hunter's Mark, питомец вперёд, затем Serpent Sting. Arcane Shot, когда есть мана. Если монстр добрался: Disengage. С несколькими монстрами: Multi-Shot вместо Aimed Shot.",
    ["c943332"] = "Основа — ястребы (Summon Hawk): каждый ястреб держится 18 секунд, двое могут быть вызваны; призывайте нового, когда один из двух исчезает. Затем Aimed Shot, когда готов, и Auto Shot в промежутках. Arcane Shot использует ту же перезарядку, что и ястребы, поэтому ждите после них. Остальное как раньше.",
    ["ab9f050"] = "Добавьте Intimidation: если монстр повернулся против вас, оглушает и даёт питомцу угрозу; Disengage, когда он не готов. С несколькими монстрами: сначала Explosive Trap, затем Multi-Shot по перезарядке Aimed Shot.",
    ["bf06335"] = "Bestial Wrath (2 минуты) и Volley остаются вне ротации: применяйте их вручную в опасных боях или с большими группами. С 42 почти все очки идут в Marksmanship: ротация не меняется.",
    ["e096af7"] = "Beast Mastery стреляет издалека: важны УВС оружия дальнего боя, затем Ловкость. Оружие ближнего боя нужно только из-за характеристик.",
    ["b35c3c9"] = "Основа — Aimed Shot каждый раз, когда он готов, с Auto Shot в промежутках. После форы питомца первый выстрел должен быть самым сильным: при ожидающем Rapid Killing это Aimed Shot. Перед боем Hunter's Mark и питомец вперёд; Serpent Sting на каждого монстра, потому что если он умрёт с Serpent Sting, ваш следующий выстрел в течение 20 секунд нанесёт до 20% больше. Arcane Shot, когда есть мана. Если монстр добрался: Disengage. С несколькими монстрами: Multi-Shot вместо Aimed Shot.",
    ["cf4e14e"] = "Перед боем также Trueshot Aura, помимо Hunter's Mark.",
    ["51e16cf"] = "Sniper Shot — ваш самый сильный выстрел: чтение 4 секунды, перезарядка 15 секунд, до 45 метров, и в течение 10 секунд ваши следующие три выстрела летят на 10 метров дальше. Используйте его как первый выстрел после форы питомца, когда есть время на чтение, лучше при ожидающем Rapid Killing; иначе Aimed Shot. С несколькими монстрами: сначала Explosive Trap, затем Multi-Shot по перезарядке Aimed Shot.",
    ["c8aaa16"] = "Основа — ястребы (Summon Hawk): новый каждый раз, когда исчезает один из двух. Затем Aimed Shot, когда готов, и Auto Shot в промежутках; Sniper Shot как первый выстрел, если есть время. Arcane Shot ждёт после ястребов.",
    ["1fe9ee6"] = "Marksmanship стреляет издалека: важны УВС оружия дальнего боя (при прочих равных лучше более медленное с сильными ударами, потому что Aimed Shot основан на ударе оружия) и Ловкость. С Careful Aim Интеллект также считается силой атаки, помимо маны. Оружие ближнего боя нужно только из-за характеристик.",
    ["184fc61"] = "Survival сражается в двух местах. Издалека: Multi-Shot каждый раз, когда готов (он мгновенный и делит перезарядку с Aimed Shot, так что Aimed Shot вы почти не используете), плюс Serpent Sting, Arcane Shot и Auto Shot. В ближнем бою: Immolation Trap, затем Raptor Strike (мгновенный, перезарядка 6 секунд) и Mongoose Bite после уклонения. Hunter's Mark перед боем, и питомец идёт первым.",
    ["d85837a"] = "Strider Kick: удар ногой с полным уроном оружия, делающий вас на 30% быстрее на 3 секунды: это кнопка, которая завершает ближний бой и возвращает вас на расстояние. В ближнем бою сначала Immolation Trap, Mongoose Bite, когда можно, Raptor Strike. На расстоянии Multi-Shot, когда готов, Serpent Sting, Arcane Shot, Auto Shot. С несколькими монстрами Explosive Trap занимает место Immolation Trap, потому что одна перезарядка действует на все ловушки.",
    ["e7233e1"] = "С Lacerating Strikes каждый Mongoose Bite оставляет кровотечение, равное 40% урона удара, за 21 секунду.",
    ["10bfe36"] = "Survival стреляет, но и бьёт оружием ближнего боя (Raptor Strike и Strider Kick основаны на его уроне): медленное двуручное помогает. Затем важна Ловкость. С 49 Careful Aim делает Интеллект полезным и как силу атаки.",
    ["0718298"] = "Blink, Evocation, Mana Shield, Blizzard, Fire Ward, телепортация в две столицы (и Arcane Blast для Arcane и Fire)",
    ["ad986c1"] = "Conjure Mana Agate (первый камень маны)",
    ["3e67dd9"] = "Ice Armor; классовое задание (жезл Ice Fury)",
    ["3ddbf7c"] = "Frostfire Bolt, первые порталы",
    ["3d9e7fb"] = "Всегда держите Arcane Intellect и заклинание брони (пока Frost Armor). Восстановление маны останавливается на 5 секунд после каждого заклинания, которое тратит ману: почти мёртвый монстр не стоит полного заклинания. Около 5 уровня возьмите жезл (Зачарователь делает Lesser Magic Wand, Greater Magic Wand с 13): до талантов он может наносить столько же урона, сколько ваши заклинания, или больше и не тратит ману.",
    ["2991425"] = "Начинайте с Frostbolt на максимальной дальности, чтобы монстр подошёл замедленным. Продолжайте читать, пока он приближается, затем Fire Blast для добивания и жезл для остатка.",
    ["5d6b9a7"] = "Frost Nova замораживает всё вокруг вас: урон её разрушает, так что можно отступать и продолжать читать. Если монстр дошёл до ближнего боя: Frost Nova и отступайте.",
    ["11f2d67"] = "С Missile Barrage: начинайте издалека с Frostbolt (Arcane и Frost) или Fireball (Fire), продолжайте читать, и когда срабатывает проц, применяйте Arcane Missiles: они становятся бесплатным залпом. Missile Barrage — талант, который больше всего экономит ману при прокачке.",
    ["b985201"] = "Evocation — поддерживаемое заклинание на 8 секунд, возвращающее большую часть маны. Blink по перезарядке во время бега позволяет добраться примерно на пятую часть быстрее. Камень возвращения лучше использовать для зоны заданий, потому что телепорт и так переносит вас в столицу.",
    ["a601e53"] = "Arcane Blast: каждое чтение даёт урон от заклинаний, равный 12% вашего Интеллекта, до 4 зарядов, которые держатся 18 секунд; каждый заряд делает следующее чтение дороже на 100%. Frostbolt издалека, затем Arcane Blast от одного до трёх раз, пока не сработает Missile Barrage, затем Arcane Missiles. Дайте зарядам истечь, не доводя до четырёх. Тратьте Clear Casting на заряженный Arcane Blast. В ближнем бою: Frost Nova и отступайте. Fire Blast для добивания и жезл.",
    ["e55eb73"] = "Arcane Wrath: тяжёлый удар с перезарядкой 6 секунд (дополнительный урон равен 5% вашей максимальной маны). Frostbolt издалека, затем Arcane Wrath, Arcane Blast от одного до трёх раз до Missile Barrage и Arcane Missiles; Frost Nova, когда он приближается, снова Arcane Wrath, затем Fire Blast и жезл для убийства. Дайте зарядам истечь, иначе растущая стоимость вас опустошит; Clear Casting только на заряженный Arcane Blast или Arcane Wrath, никогда на дешёвое заклинание.",
    ["65a5bf0"] = "Presence of Mind: ваше следующее заклинание с временем чтения меньше 10 секунд становится мгновенным.",
    ["c51b464"] = "Arcane Power: +30% урона на 15 секунд ценой +30% маны.",
    ["dfc4101"] = "Начинайте с Pyroblast или Frostbolt издалека, затем Arcane Wrath. Arcane Blast от одного до трёх раз до Missile Barrage, затем ракеты. С 58 Fire Blast по перезарядке и Pyroblast, когда Heating Up достигает 3 зарядов.",
    ["9226a40"] = "Для любой специализации на первом месте сила заклинаний, потому что ваши заклинания сильно растут от неё. Интеллект увеличивает ману и немного крит; Дух сокращает паузы на питьё, а для Arcane он очень важен, потому что она быстро тратит ману.",
    ["ebbbb02"] = "Fireball издалека. Один-два Arcane Blast, пока не сработает Missile Barrage, затем ракеты. Fire Blast по перезарядке. Монстра с малым запасом здоровья не нужно держать на расстоянии: пусть он ударит вас несколько раз, ниже 15% его добьёт жезл.",
    ["9e5f918"] = "Scorch заполняет промежутки, даже когда монстр рядом.",
    ["ab79a6b"] = "Начинайте с Frostfire Bolt издалека, затем один-два Arcane Blast, пока не сработает Missile Barrage, и ракеты. Fire Blast по перезарядке, Scorch для заполнения промежутков, жезл для последних 15%.",
    ["bece8ec"] = "Pyroblast и Heating Up: каждый непериодический крит Fireball, Frostfire Bolt, Fire Blast или Scorch делает ваш следующий Pyroblast на четверть быстрее, до 3 зарядов, а Fire Blast добавляет заряд при каждом уроне. Применяйте Pyroblast, когда Heating Up достигает 3 зарядов.",
    ["196edb9"] = "Для любой специализации на первом месте сила заклинаний. Интеллект увеличивает ману и немного крит; Дух сокращает паузы на питьё.",
    ["38bc29a"] = "Frost начинает с Precision: два очка поднимают шанс попасть по монстрам вашего уровня до 100%.",
    ["c690916"] = "Frostbite: ваши эффекты холода с шансом 15% замораживают цель на 5 секунд. Ice Lance (с 27): против замороженной цели наносит на 300% больше, перезарядка 8 секунд общая с Fire Blast.",
    ["1f1ed9a"] = "Frostbolt издалека и продолжайте читать, пока монстр подходит. Когда Frostbite замораживает цель: Frostbolt с Ice Lance сразу за ним; если Ice Lance не готов, Cone of Cold. В ближнем бою: Frost Nova и отступайте, затем Frostbolt и Ice Lance по замороженному монстру. Missile Barrage: пускайте ракеты или берегите на следующего монстра, если этот почти мёртв. Fire Blast или жезл для слабого незамороженного монстра.",
    ["2e43c7c"] = "С Fingers of Frost ваши следующие два заклинания считают цель замороженной: первое на Frostbolt, второе на Frostbolt с Ice Lance (или с Cone of Cold, если Ice Lance ещё не готов). Его сила в тридцатых: после Shatter замороженная цель получает ваши самые сильные удары.",
    ["cecd125"] = "Сначала Ice Barrier, и применяйте снова, когда истекает минута: помимо щита он даёт на минуту +15% урона льдом.",
    ["959453a"] = "Winter's Chill: Frostbolt и Ice Lance накладывают его на цель до 5 раз, и следующий Cone of Cold наносит на 20% больше за каждый заряд.",
    ["5a9d3eb"] = "Redemption (классовое задание)",
    ["3d343ad"] = "Seal of Command (талант Retribution), Seal of Justice",
    ["32b558d"] = "Двойная специализация и ездовое животное",
    ["38d0905"] = "Перед боем Blessing of Might и Devotion Aura. Затем три шага: Seal of Righteousness, Judgment во время бега к монстру, Holy Strike. Дальше Judgment и Holy Strike каждый раз, когда готовы, а печать обновляйте только когда она вот-вот закончится (Judgment больше её не расходует и не зависит от общей перезарядки). Мана — это и ваше лечение: если следующий удар убьёт монстра, пропустите кнопку. Если бой закончился с лишней маной, превратите её в здоровье через Holy Light. В опасности: сначала Divine Protection на себя, затем лечение.",
    ["f580de7"] = "Consecration, когда вы сражаетесь с несколькими врагами или у вас лишняя мана: он стоит больше, чем Judgment и Holy Strike вместе, и ему нужно 8 секунд, чтобы нанести весь урон. Exorcism по каждой нежити или демону, даже с 30 метров.",
    ["2ea2c89"] = "Добавьте Hammer of Wrath: он добивает врагов ниже 20% здоровья.",
    ["c8d4778"] = "Retribution и Protection начинают в одном дереве почти с теми же талантами. Вместо Deflection (5% парирования) можно выбрать Benediction: все мгновенные умения стоят на 10% меньше маны, и Consecration становится проще оплатить.",
    ["a81d5b1"] = "С Seal of Command: Blessing of Kings или Might и Retribution Aura. На монстра, который живёт долго: сначала Judgment от Seal of the Crusader (монстр получает больше урона от святости), затем переходите на Seal of Command, если у вас медленное оружие; с быстрым оружием или большим уроном от заклинаний лучше Seal of Righteousness. Затем Judgment и Holy Strike при каждой перезарядке. Хитрость: Judgment от Seal of Command наносит почти вдвое больше по оглушённой цели, так что начните с Hammer of Justice, затем Judgment.",
    ["733e5e6"] = "Sacred Arbiter: Holy Strike бьёт на 20% сильнее и обновляет каждый Judgment на цели, даже чужих паладинов.",
    ["a01f90a"] = "Champion of the Light превращает до 60% вашего Интеллекта в урон от заклинаний: экипировка с силой заклинаний становится ещё лучше. На 40 Unsealed Wrath: удары сохраняют копию активной печати (до 3), и смена печати снова оправдана.",
    ["5f3698b"] = "Оружие — самое важное: в идеале с силой заклинаний и большим уроном. С Seal of Command лучшие — медленные тяжёлые виды оружия (Holy Strike и печать наносят больше урона). Из остального сначала Сила или сила атаки, затем Выносливость, затем сила заклинаний.",
    ["4c063de"] = "Holy начинается как Retribution: первые 12 очков (до 21 уровня) идут в Retribution, ради эффективности маны и Pursuit of Justice. До 20 уровня твои исцеления — Holy Light, Lay on Hands и Blessing of Protection: в одиночных заданиях используй Seal of Righteousness, Judgment и Holy Strike, как паладин урона, не тратя ману впустую.",
    ["e1a4083"] = "С Flash of Light у тебя два исцеления: Holy Light медленное и сильное, когда нужно много здоровья и есть время; Flash of Light быстрое и дешевле, для небольшого постоянного урона. Выбрать нужное исцеление — вся работа: неправильное сжигает ману. С 20 уровня также Consecration, Exorcism и Blessing of Kings.",
    ["42143bb"] = "С 22 уровня очки идут в Holy: Spiritual Focus (получаемые удары меньше задерживают твои заклинания), затем Reverence (часть восстановления маны продолжается во время чтения заклинаний) и Healing Light (больше исцеления для Holy Light, Flash of Light и Holy Shock).",
    ["a1c4391"] = "Как лечить: если танк получает постоянный урон, используй Flash of Light или Holy Light; при внезапном уроне — Holy Shock; в аварийной ситуации — Lay on Hands (тратит всю ману). Blessing of Protection на союзника, получающего физический урон, но никогда на танка: если он станет неуязвимым, враги повернутся к остальным.",
    ["e98c82f"] = "Illumination: критическое исцеление Flash of Light, Holy Light или Holy Shock может вернуть ману (половину базовой стоимости), поэтому важны Интеллект и критический удар. С 37 уровня Oath of Light на основную цель; с 38 Infusion of Light: критическое исцеление Holy Shock или Flash of Light ускоряет следующий Holy Light.",
    ["3bb92dd"] = "На 40 уровне открывается двойная специализация (оставь Retribution второй специализацией для одиночных заданий) и латные доспехи. С 42 Holy Shock: мгновенное исцеление с перезарядкой 10 секунд или урон светом по врагу. С 45 Divine Favor: следующее исцеление всегда критическое (перезарядка 2 минуты), на случай опасности для танка. С 47 Holy Power повышает шанс крита у Holy Shock и Holy Strike.",
    ["31364c3"] = "Light's Vigil: эффект на 30 секунд на союзнике; Holy Shock по той же цели запускает его, лечит и группу и не запускает перезарядку Holy Shock. Он дорогой, и на группу может быть только один: прибереги его для урона по нескольким игрокам. На враге возвращает 75% маны. Последние очки (с 56) идут в Divine Intellect.",
    ["7fda0df"] = "Для Holy сначала сила исцеления, затем Интеллект (больше маны и критов, которые возвращают ману через Illumination), затем мана за 5 секунд и Дух (с Reverence часть восстановления продолжается во время чтения заклинаний). Оружие ценится за характеристики, а не за урон: булава с исцелением и Духом лучше оружия с большим DPS. Кольчуга до 40, затем латы, но тканевый предмет с нужными характеристиками ценнее кольчужного без них.",
    ["a531e3f"] = "Seal of Fury — печать танка: каждый удар наносит дополнительный урон святостью, а со щитом вы получаете поглощение, равное половине этого урона. Его Judgment заставляет вас провоцировать 3 секунды с 10 метров. Righteous Fury увеличивает всю вашу угрозу на 33%. С 22 вы переходите в дерево Protection, после Pursuit of Justice.",
    ["8279baa"] = "Blessing of Kings, Retribution Aura и Righteous Fury включены. Всегда держите Seal of Fury. Применяйте Judgment на бегу к монстру, чтобы спровоцировать. Ставьте Consecration, как только вы в ближнем бою, если хватает маны. Затем Holy Strike при каждой перезарядке и Exorcism по нежити и демонам. Соберите до четырёх врагов и сожгите всех Consecration.",
    ["34e2900"] = "Shield Specialization: блок возвращает 4% максимальной маны, не чаще раза в 3 секунды: это большая часть вашей маны.",
    ["cc3ac76"] = "Templar's Bulwark: щит, поглощающий урон, равный всему вашему здоровью, на 8 секунд, но даёт вам Forbearance на минуту. С 37 Swift Judgement: Judgment печати срабатывает сам с перезарядкой 1 минута, так что у вас есть вторая провокация.",
    ["be55413"] = "Holy Shield: на 10 секунд вы блокируете чаще, и до 4 блоков наносят урон святостью. Reckoning (с 43) может дать дополнительную атаку после блока или полученного крита.",
    ["e76d8e9"] = "Для Protection на первом месте сила заклинаний (Seal of Fury, Holy Shield и Consecration наносят урон святостью), затем Сила и Выносливость. Для оружия лучше более быстрое: Seal of Fury срабатывает при каждом ударе. Оружие с силой заклинаний может стоить немного меньшего урона.",
    ["05e5db7"] = "Shadow Word: Pain; короткое классовое задание (мантия)",
    ["c95888a"] = "Mind Blast, Resurrection; расовое задание обучает первому умению только вашей расы",
    ["091c0cd"] = "Holy Fire, Flash Heal, Devouring Plague, Fear Ward, Mind Soothe, Shackle Undead; второе расовое умение",
    ["71b2a72"] = "Fortitude на себя перед боем. Начинайте с Smite, наложите Shadow Word: Pain на цель и добивайте жезлом, который не тратит ману и в начале наносит большую часть вашего урона (стойте неподвижно полсекунды перед его использованием). Если монстр добрался до вас, сначала Power Word: Shield. Важнее всего иметь хороший жезл: меняйте его каждый раз, когда находите лучше.",
    ["e023128"] = "Mind Blast — сильный удар с короткой перезарядкой. Первые семь очков талантов одинаковы для всех специализаций: Wand Specialization (10-11) и Spirit Tap (12-16). С Spirit Tap каждое убийство монстра, дающего опыт, удваивает ваш Дух на 15 секунд, и всё это время половина восстановления маны продолжается во время чтения: меньше пауз на питьё.",
    ["8df287d"] = "Inner Fire: дополнительная броня, каждый полученный удар расходует заряд. Держите его вместе с Fortitude всегда на себе и накладывайте снова, когда закончится.",
    ["bebe913"] = "Psychic Scream заставляет ближних врагов бежать, но осторожно: они могут привести других монстров.",
    ["ffa87bf"] = "Наставник сегодня учит вас больше, чем на любом другом уровне: Holy Fire (медленное, но сильное начало, ещё и горит со временем), Flash Heal (быстрое, но дорогое), Devouring Plague (урон со временем, который вас лечит) и другие.",
    ["084f80e"] = "Shadow — рекомендуемая специализация для прокачки в одиночку: очки идут в Shadow Word: Pain, Mind Blast и Mind Flay, так что монстры умирают быстрее.",
    ["f33a503"] = "Ставьте Shield на себя, если монстр добрался. Начинайте с Mind Blast, затем Shadow Word: Pain. С 27 также Devouring Plague и Mind Flay, а после Shadow Word: Pain добавьте Vampiric Embrace, чтобы урон тенью лечил вас. Затем добивайте жезлом. Если маны мало, пропустите Devouring Plague и Mind Flay.",
    ["496ef3d"] = "Shadow Word: Death — внезапный урон, но если цель выживет, вы получите 30% своего максимального здоровья: берегите его для последнего удара.",
    ["edd0d02"] = "Shadowform: оставайтесь в Shadowform во время боя (+10% урона тенью, заклинания тени стоят вдвое меньше маны, -15% физического урона, но нельзя читать лечение: выходите перед лечением). Начинайте с Mind Blast, затем Shadow Word: Pain, Vampiric Embrace, Devouring Plague и Mind Flay. Когда ещё один удар убьёт монстра: Shadow Word: Death или оставьте последний кусочек жезлу. Shield на себя, если монстр добрался.",
    ["b912dce"] = "Для Shadow на первом месте сила заклинаний (сила теней тоже подойдёт: почти весь ваш урон — тень), затем крит и Меткость (Hit). Жезл очень важен: в начале он наносит большую часть урона.",
    ["8e3f775"] = "Discipline — специализация лечения, которую мы рекомендуем для игры в одиночку: с 20 Power in Light добавляет урон Smite.",
    ["916c9c2"] = "Начинайте с Holy Fire издалека, Smite, пока монстр подходит, затем Mind Blast, Shadow Word: Pain и жезл. Если бой идёт плохо: Shield на себя, затем лечитесь: Flash Heal, если нужно быстро, Heal, если есть время.",
    ["a80f7e5"] = "Penance: серия святых ударов, которая ранит врага или лечит союзника, перезарядка 12 секунд, первый удар наносится сразу.",
    ["037a666"] = "Сначала Shield на себя. Начинайте с Holy Fire издалека. Smite, пока монстр идёт, затем Penance по той же цели, потому что Power in Light делает его сильнее. Затем Mind Blast и Shadow Word: Pain. Для добивания Shadow Word: Death, если удар убивает, иначе жезл. Каждый раз, когда Weakened Soul пропадает, вы можете защитить себя снова.",
    ["9d0affc"] = "Power Infusion: +20% урона и исцеления на 15 секунд, на себя или друга: применяйте на себя перед самым началом боя при каждой готовности. На 60 Inner Focus для экстренных случаев: следующее заклинание бесплатно.",
    ["8e7cd8d"] = "Для Discipline и Holy ищите силу исцеления и восстановление маны, затем Интеллект и Дух. Выбирайте оружие с теми же характеристиками: неважно, посох это или одноручное с предметом для второй руки.",
    ["c5c1351"] = "Поставьте Shield и Renew на себя перед боем. Затем начинайте с Holy Fire, Smite, пока монстр подходит, Mind Blast и Shadow Word: Pain. Заканчивайте Shadow Word: Death, если убивает, или жезлом.",
    ["575bdd0"] = "Holy Nova ранит каждого ближнего врага и лечит группу: стоит много маны, так что используйте её, когда на вас несколько врагов, или когда она бесплатна (Searing Light с 43: Holy Fire может сделать следующую Holy Nova бесплатной).",
    ["6953353"] = "Перед боем поставьте на себя Shield, Renew и Prayer of Mending (лечит при следующем уроне по цели, затем перескакивает на другого в группе, перезарядка 10 секунд).",
    ["a5c9096"] = "Для Holy ищите силу исцеления и восстановление маны, затем Интеллект и Дух. Выбирайте оружие с теми же характеристиками.",
    ["aa71e89"] = "Backstab (нужен кинжал, только со спины), Pick Pocket",
    ["2e3c463"] = "Slice and Dice, Sprint, Sap; классовое задание (Blade of Cunning)",
    ["3a2246d"] = "Ambush (нужен кинжал), Poised (пассивное)",
    ["8abd601"] = "Rupture; задание на яды: Instant Poison и Crippling Poison",
    ["6c840ea"] = "Shank (новое в Forever)",
    ["f3d428e"] = "Mutilate (талант Assassination)",
    ["3e307c7"] = "Death Mark (талант Subtlety), Slice and Dice ранг 2",
    ["f14c847"] = "Shank ранг 2",
    ["a554ba3"] = "Подойдите к монстру и используйте Sinister Strike, пока есть приёмы в серии, затем Eviscerate: больше приёмов — сильнее удар. Stealth пока может остаться на панели. Если бой идёт плохо: Evasion и Gouge, чтобы прервать заклинание или выиграть пару секунд.",
    ["44b2b7e"] = "Slice and Dice (завершающий приём: вы атакуете на 20% быстрее, дольше при большем числе приёмов), Sprint (на 50% быстрее на 15 секунд, не снимает Stealth) и Sap, чтобы убрать гуманоида из боя до начала.",
    ["665b56f"] = "Rupture: более долгое кровотечение при большем числе приёмов. С заданием на яды Instant Poison и Crippling Poison.",
    ["d06b2e0"] = "Shank: удар второй рукой, который не может промахнуться; первый ранг стоит 5 энергии, возвращает 15 и перезаряжается за 10 секунд. С 26 Cheap Shot из невидимости: оглушает на 4 секунды и даёт 2 приёма.",
    ["6974c7f"] = "Combat — дуэлянт: он сражается в ближнем бою тем оружием, которое вы предпочитаете, работает с любым оружием и не нуждается в невидимости для начала. Это рекомендуемая специализация для прокачки в одиночку.",
    ["cea5a19"] = "Riposte: после вашего парирования загорается и бьёт на полтора урона оружия, обезоруживает монстра на 6 секунд и стоит всего 10 энергии с перезарядкой 6 секунд.",
    ["5288c4d"] = "Instant Poison на оба оружия. Cheap Shot из невидимости для тяжёлого боя, иначе сразу Sinister Strike. Riposte сразу после парирования. Sinister Strike для приёмов, пока Shank на перезарядке: первые пять приёмов в Slice and Dice, следующие пять в Eviscerate.",
    ["869d1bf"] = "С двумя монстрами на вас: Blade Flurry (раз в 2 минуты, 15 секунд вы атакуете на 20% быстрее, и каждый удар задевает ещё одного ближнего).",
    ["9fb5eb8"] = "Adrenaline Rush (раз в 5 минут: энергия восстанавливается вдвое быстрее 15 секунд) для опасного монстра.",
    ["f8cc28b"] = "Cold Blood непосредственно перед сильным Eviscerate.",
    ["625324b"] = "Кожаная броня с Ловкостью: именно она вам нужна. Меткость (Hit), крит, сила атаки и Выносливость полезны. Combat может использовать любое оружие, потому что Hack and Slash даёт бонус к каждому виду: мечи и топоры, кинжалы и кистевое оружие, булавы.",
    ["d01cb25"] = "Assassination — отравитель: яды и завершающие приёмы становятся всё сильнее, а на 40 приходит Mutilate.",
    ["9eb3d72"] = "Instant Poison на оба оружия. Из невидимости начинайте с Garrote или Cheap Shot. Sinister Strike для приёмов и Shank по перезарядке. Slice and Dice, затем Eviscerate; берегите Cold Blood для сильного Eviscerate.",
    ["33aceb3"] = "Venom: в течение 6 секунд после каждого Shank ваши яды бьют на 30% сильнее и на 20% чаще. Shank по перезарядке.",
    ["88ede56"] = "Mutilate набирает приёмы: бьёт обоими оружиями, на 20% сильнее по отравленной цели, и даёт 2 приёма. Нужны два кинжала. Slice and Dice, Shank по перезарядке для Venom, затем Eviscerate; Cold Blood на сильный Eviscerate.",
    ["20500ff"] = "Кожаная броня с Ловкостью. Assassination нужны кинжалы для Backstab, Ambush и Mutilate. Меткость (Hit), крит, сила атаки и Выносливость полезны.",
    ["5259278"] = "Subtlety — засадник: начинает каждый бой из тени с кинжалом в руке.",
    ["64f4a07"] = "Кинжал в основной руке, Instant Poison на оба оружия. Подойдите к монстру со спины, Premeditation, затем Ambush, затем Ghostly Strike, затем Garrote. Sinister Strike набирает остальное; Shank по перезарядке ради энергии; Eviscerate завершает.",
    ["37c1365"] = "Hemorrhage набирает приёмы вместо Sinister Strike.",
    ["c0f22d5"] = "Hemorrhage и Shank набирают приёмы, а с Boot Knife каждый Shank стоит двух. Death Mark накапливает урон 6 секунд: потратьте на него полный набор приёмов, когда монстр живёт достаточно долго, затем Eviscerate для завершения. Если бой идёт плохо, Preparation сбрасывает Premeditation, Ghostly Strike и другие ваши перезарядки.",
    ["a993dd2"] = "Кожаная броня с Ловкостью. Subtlety держит кинжал в основной руке (Ambush и Backstab требуют его). Меткость (Hit), крит, сила атаки и Выносливость полезны.",
    ["abbb551"] = "Earth Shock; задание тотема земли: Stoneskin Totem",
    ["8e8845b"] = "Задание тотема огня: Searing Totem",
    ["2be8a5e"] = "Ghost Wolf, Frost Shock, Lesser Healing Wave, Frostbrand Weapon, Healing Stream Totem (задание тотема воды), Call of the Elements, Totemic Recall",
    ["0a8c77d"] = "Windfury Weapon, Reincarnation (нужен Ankh), Astral Recall, Grounding Totem",
    ["47fd721"] = "Chain Lightning, Windfury Totem; задание тотема воздуха (оружие бури)",
    ["b821239"] = "Chain Heal, кольчужная броня",
    ["d6b5209"] = "Rockbiter Weapon остаётся на оружии, а с 8 Lightning Shield ставится перед боем. Начинайте с Lightning Bolt и, как только монстр подойдёт, Earth Shock, он мгновенный; против заклинателя берегите шок, чтобы прервать его заклинание. Когда монстр рядом, его добивают удары в ближнем бою. Если подходит другой монстр, поставьте Earthbind Totem: он замедляет его и позволяет кайтить. После боя Healing Wave, если вы ранены.",
    ["fa734a3"] = "У каждой специализации чёткая роль: Enhancement сражается в ближнем бою с большим оружием, тотемами и шоками; Elemental держится на расстоянии с Lightning Bolt, Chain Lightning и Fire Nova; Restoration лечит и играет в группе или в подземельях, а не в одиночку на заданиях. Если мана закончилась, Enhancement продолжает бить (убийство занимает дольше), Elemental страдает сильнее.",
    ["b74be3c"] = "Flame Shock бьёт сразу огнём, а затем горит 12 секунд. Flametongue Weapon добавляет урон огнём к каждому удару; Searing Totem — маленькая турель, стреляющая по ближнему врагу.",
    ["35c7293"] = "Enhancement — специализация, которую мы рекомендуем для заданий. У неё есть слабые места: плохое оружие сильно снижает урон, затраты маны в начале ощутимы, а против многих врагов сразу ей тяжело.",
    ["028a6b7"] = "Stormstrike бьёт сразу полным уроном оружия раз в 8 секунд, и цель получает на 20% больше от вашего следующего Lightning Bolt, Chain Lightning или Earth Shock.",
    ["a94041d"] = "Stormstrike каждый раз, когда готов, и сразу после него Earth Shock (удар Stormstrike усиливает шок). Rockbiter Weapon всегда на оружии и Lightning Shield на себе. Перед боем Strength of Earth и Mana Spring и, если хватает маны, Searing Totem или Magma Totem. Начинайте с Lightning Bolt ранга 1 (самый дешёвый), остальное делают обычные удары. Fire Nova только если монстры в радиусе вашего огненного тотема и ещё есть мана. После убийства Healing Wave и пейте, если маны мало.",
    ["18a8896"] = "Windfury Weapon на оружие вместо Rockbiter: каждый удар с шансом 20% даёт две дополнительные атаки, это главная деталь Enhancement. Если уклонение или парирование сбросило Stormstrike, нажмите его снова сразу. Windfury Totem, а против заклинателей Grounding Totem вместо него.",
    ["f3777c4"] = "Maelstrom Weapon: ваши удары копят до 5 зарядов, и каждый заряд делает следующий Lightning Bolt быстрее и дешевле: с 5 зарядами применяйте Lightning Bolt максимального ранга. С 46 Water Shield занимает место Lightning Shield (можно иметь только один).",
    ["022a55d"] = "Для Enhancement оружие важнее всего: идеально медленное двуручное со скоростью от 3,3 до 3,8. Затем Сила и сила атаки, а сразу за ними Интеллект, потому что он питает Mental Dexterity и ману.",
    ["4540d89"] = "Earthbound: когда вы ставите Earthbind Totem, ближние враги остаются обездвиженными на 5 секунд.",
    ["bcd1d77"] = "Перед боем Mana Spring Totem и огненный тотем (Searing против одного монстра, Magma против нескольких), Lightning Shield на себя. Начинайте на пределе дальности с Lightning Bolt, наложите Flame Shock на цель и продолжайте Lightning Bolt. С тремя и более монстрами Fire Nova каждый раз, когда готов. Earth Shock прерывает заклинателя и приводит его к вам. Earthbind Totem, когда монстры приближаются. Лечитесь и пейте в конце.",
    ["13a3832"] = "Против одного монстра: Searing Totem, начинайте издалека с Lightning Bolt, Flame Shock, продолжайте Lightning Bolt. Против трёх и более: Magma Totem, начинайте с Chain Lightning, Flame Shock на одного из них, затем Chain Lightning и Fire Nova при каждой перезарядке с Lightning Bolt между ними.",
    ["2c3ba7a"] = "Lightning Mastery (15 секунд, затем 3 минуты): 15 секунд Lightning Bolt читается быстрее, а Chain Lightning игнорирует свою перезарядку. Используйте на элите или большой пачке, иначе при каждой перезарядке.",
    ["b56c9ed"] = "Water Shield занимает место Lightning Shield на вас.",
    ["4688073"] = "Для Elemental ищите силу заклинаний, а Интеллект — в основном ради маны. С 40 уровня можно носить кольчугу.",
    ["b4ca62b"] = "Перед боем Water Shield, Mana Spring Totem и тотемы, которыми может пользоваться группа. Пока кто-то получает урон, Healing Wave — рабочая лошадка. Lesser Healing Wave читается 1,5 секунды и лечит меньше за ману: берегите её для моментов, когда важно время. Mana Tide Totem (12 секунд, перезарядка 5 минут), когда у всей группы кончилась мана. Когда никому ничего не угрожает, добавьте урон: Lightning Bolt по цели, Fire Nova по группе. Пейте в конце.",
    ["42937c0"] = "Nature's Swiftness (раз в 3 минуты): ваше следующее заклинание природы мгновенное, то есть мгновенный Healing Wave для друга, который вот-вот умрёт. Windfury Totem, если в ближнем бою есть игроки.",
    ["9b2d19c"] = "Riptide: исцеление со временем с перезарядкой 12 секунд, а Chain Heal, применённый именно на цель Riptide, сильнее на 25%. Chain Heal лечит цель и ещё двух союзников, поэтому покрывает урон, распределённый по группе.",
    ["a86408d"] = "Для Restoration ищите силу исцеления, а Интеллект — в основном ради маны. С 40 уровня можно носить кольчугу.",
    ["c86a1be"] = "Voidwalker (классовое задание), Drain Soul, Healthstone",
    ["40cb6b4"] = "Succubus и Incubus (классовые задания), Demon Armor, Curse of the Elements, Rain of Fire, Ritual of Summoning",
    ["df7bfa2"] = "Felhunter (классовое задание), Hellfire",
    ["19e5308"] = "Howl of Terror, Felsteed (задание)",
    ["1c5b068"] = "Демон идёт первым, затем Bane of Agony и Corruption; Immolate получают только самые крепкие монстры, потому что демон их удерживает. Порядок важен, потому что урон привлекает внимание: первые тики Agony малы, поэтому демон удерживает монстра, пока свежий Immolate не ударит достаточно сильно, чтобы тот повернулся к вам. Держите Demon Skin, пропускайте DOT на почти мёртвом монстре и не обновляйте Agony, пока он ещё наносит урон. Пока нет жезла, работу заканчивает Shadow Bolt; затем возьмите жезл: каждый выстрел — сэкономленная мана на следующий бой.",
    ["ea42414"] = "Drain Soul — ваш основной источник Soul Shard: нетривиальный монстр, умерший от его Drain, всегда даёт один. Когда осколков мало, добивайте им. Healthstone, Soul Stone и призыв Voidwalker, Succubus и Felhunter требуют осколков.",
    ["72f97d5"] = "Drain Life меняет то, как вы смотрите на экран: если синяя полоса низкая, а здоровье в порядке, Life Tap; если здоровье действительно упало, Drain Life по монстру. Так почти весь простой исчезает.",
    ["51205f3"] = "Demon Armor вместо Demon Skin. С Ritual of Summoning вы и двое спутников приводите члена группы, который ещё далеко. Fear даёт вам несколько бесплатных секунд на повязку.",
    ["9d83c05"] = "Если вы играете в одиночку, Affliction — лучший выбор: меткость и мгновенная Corruption приходят рано. Curse of the Elements ставится рядом с Agony. С 25 Nightfall может срабатывать от урона Corruption, Drain Life или Drain Soul, и Shadow Bolt после проца читается мгновенно. Талант дренажей можно взять немного раньше 30 и опираться на Drain Life в каждом бою.",
    ["04f03c2"] = "Siphon Life: тик каждые 3 секунды в течение 30 секунд, так что монстр, умирающий за 10, получает лишь треть. Берегите его для долгих боёв.",
    ["703c37f"] = "Demonic Sacrifice: вы жертвуете Felhunter и в течение двух часов восстанавливаете 3% всего здоровья каждые 4 секунды; призыв демона отменяет это, так что отсюда вы выполняете задания почти без питомца.",
    ["2dbcea6"] = "Wrack: вы поддерживаете заклинание 6 секунд, оно наносит урон тенью, а ваши остальные DOT тени на этой цели бьют на 10% сильнее, пока оно действует.",
    ["edb7e47"] = "Выбирайте оружие с силой заклинаний, потому что бить им вы почти не будете. В начале улучшение жезла перевешивает почти всё остальное; позже на первом месте сила заклинаний. Выносливость — лишнее здоровье, чтобы превращать его в ману через Life Tap, Интеллект — больший запас маны, Дух даёт больше при каждом Life Tap.",
    ["1c3a6a3"] = "Если вы предпочитаете смотреть, как работает демон, Demonology: с Demonic Brand с 25. С 25 Searing Pain ставит на цель метку на 10 секунд, и не более первых шести ударов вашего демона наносят дополнительный урон: обновляйте её быстрым Searing Pain по тому, с кем сражается демон, и заполняйте промежутки DOT и жезлом.",
    ["00d4a86"] = "Soul Link: 30% каждого прямого удара по вам уходит демону, и вы оба наносите на 3% больше урона. Теряется при смене демона: накладывайте заново каждый раз.",
    ["a3cee7a"] = "Demonic Pact: жертва сохраняется при смене демона, если только вы не призываете того же, которого пожертвовали. В подземелье жертвуйте Imp (+15% урона тенью); на заданиях в одиночку Felhunter ради его исцелений и сражайтесь рядом с Voidwalker, Succubus или Incubus. С 27 можно также качаться как Affliction и сменить специализацию: у вас есть очки на все три ранга Demonic Brand.",
    ["545f2c9"] = "Destruction играбельна с 10, но становится намного сильнее на 39 и 40, и дольше стоит на месте, читая заклинания, чем две другие: её можно выбрать и позже.",
    ["0b5d29c"] = "Shadowburn: мгновенный удар, который стоит один Shard и возвращает его, если нетривиальная цель умирает в течение 8 секунд.",
    ["124afde"] = "Начало меняется: Shadow Bolt с максимальной дистанции и Immolate, пока болт ещё в полёте. Так монстр идёт к вам, а не к демону, поэтому выбирайте бои, которые можно закончить быстро. Shadowburn добивает монстров; Conflagrate лучше беречь на конец вашего Immolate.",
    ["07ea333"] = "С Shadow and Flame Conflagrate повышает ваш урон тенью на 20%, а Shadowburn — урон огнём на 20%; Conflagrate больше не расходует Immolate, а Shadowburn всегда возвращает Shard. С 39 нет причин их придерживать.",
    ["609f38c"] = "Incinerate наносит на 25% больше всему, что уже горит от вашего Immolate.",
    ["a1d5005"] = "Defensive Stance, Taunt, Sunder Armor (классовое задание), Bloodrage",
    ["b87bfb2"] = "Revenge, Demoralizing Shout, Tactical Mastery (изучается у наставника)",
    ["a61955b"] = "Victory Rush, Cleave, Slam, Retaliation; можно использовать два оружия",
    ["323f468"] = "Berserker Stance, Berserker Rage, Intercept (классовое задание)",
    ["b289adb"] = "Латные доспехи и ездовое животное",
    ["2debde0"] = "Battle Shout перед боем, Charge, Rend на тех, кто живёт долго, затем пусть обычные удары набирают ярость. Heroic Strike только с яростью, которая вам не нужна: он заменяет обычный удар, а тот удар ярости не даёт. С несколькими монстрами Thunder Clap; не тратьте ярость на монстра, который вот-вот умрёт.",
    ["f98c5d6"] = "Bloodrage между боями: стоит немного здоровья и даёт 10 ярости сразу и 10 через 10 секунд. Никогда не начинайте бой без ярости.",
    ["970305a"] = "Victory Rush каждый раз, когда загорается: после убийства, дающего опыт, у вас есть 20 секунд, наносит урон и лечит на 10%, перезарядка 30 секунд и не стоит ярости.",
    ["a60b4a3"] = "С 14 Revenge — ваша основная атака: используйте её каждый раз, когда загорается (после блока, уклонения или парирования). Перейдите на щит и одноручное оружие. Thunder Clap и Demoralizing Shout по группам.",
    ["41fd2f0"] = "Charge, затем оставайтесь в Defensive Stance. Держите Shield Block против тех, кто бьёт вас в ближнем бою, и пропускайте Shield Block против заклинателей. Revenge каждый раз, когда загорается; Rend и несколько Sunder Armor по монстрам, которые живут долго; Thunder Clap и Demoralizing Shout по группам.",
    ["b604238"] = "С Vanguard можно делать Charge из Defensive Stance: можно начать бой без смены стойки, если вы вне боя.",
    ["c9e7c22"] = "Shield Wall: на 12 секунд получаемый урон ниже на 60%, для боёв, которые идут плохо.",
    ["3f0c2f4"] = "Shield Slam — самый сильный удар (урон растёт с вашим значением блока): используйте его первым, а Revenge сразу после. Если ярости мало, Revenge первым, он дешевле.",
    ["846367b"] = "Protection прежде всего хочет Силу (каждое очко даёт 2 силы атаки и значение блока). Для оружия берите лучший УВС: Revenge и Shield Slam не зависят от оружия. Ловкость важна меньше: даёт крит, уклонение и броню, но не силу атаки.",
    ["fabdcb6"] = "Сначала Rend, затем Overpower каждый раз, когда загорается (после уклонения цели).",
    ["f29cf52"] = "Rend, затем Overpower, когда загорается. С 20 Slam сразу после удара.",
    ["60998aa"] = "Sweeping Strikes: ваши следующие пять ударов задевают и второго ближнего врага, это большой скачок. Начинайте с одного монстра, пока есть лишняя ярость, затем притяните второго и используйте Sweeping Strikes и Cleave по обоим.",
    ["efc030d"] = "С Bloodthrill, если Rend на цели, удары основной руки с шансом 20% запускают Overpower: Rend остаётся в ротации до 60.",
    ["98a8fec"] = "Mortal Strike — ваша новая основная атака.",
    ["7caf705"] = "Оружие важнее всего: ищите самый высокий УВС, а для Arms медленное двуручное (каждый удар, Mortal Strike и Slam наносят больше урона). Из остального сначала Меткость (Hit, потому что промах не даёт ни урона, ни ярости), затем Сила и Крит. Ловкость даёт крит и уклонение, но не силу атаки.",
    ["ce62f29"] = "Rend на монстров, которые живут долго, Overpower, когда цель уклоняется. Если рядом с целью второй монстр, потратьте лишнюю ярость на Cleave. Выбирайте быстрое оружие для второй руки: больше ударов, больше ярости.",
    ["1879df1"] = "Death Wish: на 30 секунд вы наносите на 20% больше физического урона и не можете быть испуганы, но получаете на 5% больше урона. Reckless Swings (31): стоит немного здоровья, и следующие четыре удара дают по 5 ярости больше.",
    ["0d27ce4"] = "С Whirlwind (уровень 36) это ваша главная кнопка, даже против одного монстра: перезарядка падает до 8 секунд, и он бьёт ближайшего на 30% сильнее.",
    ["308a3c5"] = "Bloodthirst каждый раз, когда Whirlwind на перезарядке. С 50 у вас есть Recklessness.",
    ["2d76abd"] = "Оружие важнее всего: ищите самый высокий УВС. Для второй руки быстрое (больше ударов, больше ярости). Из остального сначала Меткость (Hit), затем Сила и Крит. Ловкость даёт крит и уклонение, но не силу атаки.",
}
